import { z } from "zod";
import { failure } from "./failures.js";
import { RUNTIME_LIMITS } from "./limits.js";
import { ProtocolSession } from "./session.js";
import { Buffer } from "node:buffer";
import { WebSocket, WebSocketServer } from "ws";
const FILE_UPLOAD_RANK = {
    payload: 0,
    local_paths: 1,
    refused: 2,
};
export function createFileUploadTallies() {
    let current;
    return {
        record(kind) {
            if (current === undefined)
                return;
            if (current.kind === undefined || FILE_UPLOAD_RANK[kind] > FILE_UPLOAD_RANK[current.kind]) {
                current.kind = kind;
            }
        },
        begin() {
            const tally = { kind: undefined };
            current = tally;
            return () => {
                if (current === tally)
                    current = undefined;
                return tally.kind;
            };
        },
    };
}
export async function startPlaywrightRuntimeProxy(options) {
    const port = z
        .number()
        .int()
        .min(0)
        .max(65_535)
        .safeParse(options.port ?? 0);
    if (!port.success) {
        return {
            kind: "rejected",
            failure: failure("invalid_input", "Proxy port was rejected"),
        };
    }
    try {
        const mode = options.mode ?? "stock";
        const disconnectListeners = new Set();
        let activeClient;
        let activeSession;
        let expiredMessage;
        const fileUploads = createFileUploadTallies();
        const uploads = {
            roots: options.uploadRoots ?? [],
            onFileUpload: (kind) => fileUploads.record(kind),
        };
        const releaseSlot = () => {
            activeClient = undefined;
            activeSession = undefined;
            for (const listener of disconnectListeners) {
                listener();
            }
        };
        const server = new WebSocketServer({
            host: "127.0.0.1",
            port: port.data,
            maxPayload: mode === "unsafe" ? RUNTIME_LIMITS.webSocketFrameBytes : 0,
            perMessageDeflate: false,
        });
        const listening = await waitForListening(server);
        if (listening.kind === "rejected") {
            server.close();
            return listening;
        }
        const address = server.address();
        if (address === null || typeof address === "string") {
            server.close();
            return {
                kind: "rejected",
                failure: failure("launch_failed", "Proxy did not bind a TCP port"),
            };
        }
        server.on("connection", (client) => {
            if (activeClient !== undefined) {
                client.close(1008, "Only one Playwright connection is allowed");
                return;
            }
            activeClient = client;
            client.pause();
            let closedEarly = false;
            const onEarlyClose = () => {
                closedEarly = true;
                releaseSlot();
            };
            client.once("close", onEarlyClose);
            void options.upstream.connect().then((connected) => {
                client.off("close", onEarlyClose);
                client.resume();
                if (closedEarly) {
                    if (connected.kind === "admitted")
                        connected.value.close();
                    return;
                }
                if (connected.kind === "rejected") {
                    client.close(1011, closeReason(connected.failure.message));
                    releaseSlot();
                    return;
                }
                activeSession = attachClient(client, connected.value, mode, uploads, releaseSlot);
                if (expiredMessage !== undefined)
                    activeSession.expire(expiredMessage);
            }, () => {
                client.off("close", onEarlyClose);
                client.resume();
                if (closedEarly)
                    return;
                client.close(1011, "Browser connection failed");
                releaseSlot();
            });
        });
        return {
            kind: "admitted",
            value: {
                wsEndpoint: `ws://127.0.0.1:${address.port}/`,
                dropClient() {
                    activeClient?.terminate();
                },
                onClientDisconnect(listener) {
                    disconnectListeners.add(listener);
                    return () => disconnectListeners.delete(listener);
                },
                expire(message) {
                    expiredMessage = message;
                    activeSession?.expire(message);
                },
                renew() {
                    expiredMessage = undefined;
                },
                beginFileUploadTally: () => fileUploads.begin(),
                async close() {
                    activeClient?.close(1001, "Proxy closed");
                    await new Promise((resolve) => server.close(() => resolve()));
                    await options.upstream.close();
                },
            },
        };
    }
    catch {
        return {
            kind: "rejected",
            failure: failure("launch_failed", "Playwright proxy failed to start"),
        };
    }
}
function attachClient(client, upstream, mode, uploads, onDisconnect) {
    let disconnected = false;
    const disconnect = () => {
        if (disconnected) {
            return;
        }
        disconnected = true;
        upstream.close();
        if (client.readyState === WebSocket.OPEN || client.readyState === WebSocket.CONNECTING) {
            client.close(1008, "Protocol session closed");
        }
        onDisconnect();
    };
    const session = new ProtocolSession({
        sendToClient(message) {
            if (client.readyState === WebSocket.OPEN) {
                client.send(message);
            }
        },
        sendToServer(message) {
            upstream.send(message);
        },
        close(_reason) {
            disconnect();
        },
    }, mode, uploads);
    client.on("message", (data, isBinary) => {
        session.onClientFrame(isBinary ? new DataView(new ArrayBuffer(0)) : data);
    });
    upstream.onMessage((message) => session.onServerFrame(message));
    upstream.onClose(disconnect);
    client.on("close", disconnect);
    client.on("error", disconnect);
    return session;
}
function closeReason(message) {
    let reason = message;
    while (Buffer.byteLength(reason, "utf8") > 123)
        reason = reason.slice(0, -1);
    return reason;
}
function waitForListening(server) {
    return new Promise((resolve) => {
        server.once("listening", () => resolve({ kind: "admitted", value: undefined }));
        server.once("error", () => resolve({
            kind: "rejected",
            failure: failure("launch_failed", "Proxy listener failed"),
        }));
    });
}
